ch04b-elif-and-rules#9:
year = int(input("Year: "))
is_leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
if is_leap:
    print(f"{year} is a leap year")
else:
    print(f"{year} is an ordinary year")

