age = int(input("Age: "))
if not name:
    print("Please type your name.")
elif age >= 13:
    print("Welcome, " + name + "!")
else:
    print("Sorry, " + name + ", you must be 13.")

ch04d-checking-input#8:
try:
    month = int(input("Month: "))
    if 1 <= month <= 12:
        days = 31
        if month == 2:
            days = 28
        if month == 4 or month == 6 or month == 9 or month == 11:
            days = 30
        print(f"Month {month} has {days} days.")
    else:
        print("Please type a month from 1 to 12.")
except ValueError:
    print("Please type a month from 1 to 12.")

ch04e-the-ticket-kiosk#5:
try:
    age = int(input("Age: "))
    if 0 <= age <= 120:
        day = input("Day: ")
        if age < 5:
            price = 0
        elif age < 13:
            price = 8
        elif age < 65:
            price = 14
        else:
            price = 10
        if price and day == "Tuesday":
            price -= 3
        print("Price: $" + str(price))
    else:
        print("Please enter a realistic age.")
except ValueError:
    print("Age must be a whole number.")
